import { useLocation } from 'react-router-dom'; 
import './find.css';
import React, { useEffect, useState } from "react";
import Axios from "axios";

function Find() {  
    const [data, setUserList] = useState([]);
    const [filteredData, setFilteredData] = useState([]);
    const [years, setYears] = useState([]);
    const [selectedYear, setSelectedYear] = useState('');
    const location = useLocation();

    const getuser = async () => {
        try {
            const response = await Axios.get("http://localhost:3002/getdetails");
            const users = response.data.users || [];
            setUserList(users);

            // Get unique years for dropdown
            const uniqueYears = [...new Set(users.map((user) => user.year))].sort();
            setYears(uniqueYears);

            // Apply filtering initially
            setFilteredData(
                selectedYear ? users.filter(user => user.year === selectedYear) : users
            );
        } catch (error) {
            console.error("fetching error", error);
        }
    };

    useEffect(() => {
        getuser();
    }, [location]);

    useEffect(() => {
        const filtered = selectedYear
            ? data.filter(user => user.year === selectedYear)
            : data;
        setFilteredData(filtered);
    }, [selectedYear, data]);

    return ( 
        <div className='kj'> 
            <div className='tablebox'>
                <div className="filter-box">
                    <label htmlFor="year">Select Year: </label>
                    <select
                        id="year"
                        value={selectedYear}
                        onChange={(e) => setSelectedYear(e.target.value)}
                        className="year-dropdown"
                    >
                        <option value="">All Years</option>
                        {years.map((year, index) => (
                            <option key={index} value={year}>{year}</option>
                        ))}
                    </select>
                </div>

                <table border="1" className='as'>
                    <thead>
                        <tr>
                            <th>District</th>
                            <th>Stream</th>
                            <th>Course</th>
                            <th>Z-Range</th>
                        </tr>
                    </thead>
                    <tbody>
                        {filteredData.length > 0 ? (
                            filteredData.map((row, index) => (
                                <tr key={index}>
                                    <td>{row.district}</td>
                                    <td>{row.stream}</td>
                                    <td>{row.course}</td>
                                    <td>{row.zValue1} - {row.zValue2}</td>
                                </tr>
                            ))
                        ) : (
                            <tr>
                                <td colSpan="4" style={{ textAlign: 'center' }}>
                                    No data available for selected year.
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
}

export default Find;
